import os

# ─── GRAVITATION ───────────────────────────────────────────────────────────────

G = 5.0                    # Gravitational constant. C_core (M=10) dominates at r>=2.
EPSILON = 0.1              # Softening length — dampens close-approach spikes
DT = 0.01                  # Integration timestep for velocity Verlet

# ─── CORE MASS MODEL: M_core = M_base + alpha*(dD)^beta ──────────────────────

M_CORE_BASE = 10.0         # Dominates all planets (planets are 2.0–4.5)
DISSONANCE_ALPHA = 1.2     # How strongly dissonance increases effective mass
DISSONANCE_BETA = 1.8      # Exponent — higher = sharper ramp under stress

# ─── PLANET MASSES (cognitive weight / activation threshold, not grav mass) ──

