# ─── ORBITAL INITIALIZATION ──────────────────────────────────────────────────

PLANE_TILT_MAX_DEG = 5     # Max random tilt from reference orbital plane
ORBITAL_VEL_FORMULA = "circular"

# ─── RESONANCE (Phase 0D) ────────────────────────────────────────────────────

RESONANCE_THRESHOLD = 0.7  # Cosine similarity threshold for constructive resonance
RESONANCE_SIGMOID_K = 8.0  # Sharpness of sigmoid ramp above threshold
# Resonance_n = 1 / (1 + exp(-k * (similarity - threshold)))
#
# RESONANCE_MULTIPLIER_ENABLED : Phase 1 "resonance multiplier" knob — ON by default.
#   When True, routing.py multiplies each planet's field-derived activation weight by
#   sigmoid(k*(sim - threshold)) using its semantic-identity cosine. When False,
#   the output is byte-identical to the no-multiplier path so it can be A/B'd later with
#   zero rewrite. Kept because collapse()'s consensus+tension already IS the interference
#   mechanic in practice; stacking a second sigmoid on top risks double-counting (see D-018 §7b/7c).
#   NOTE: was originally OFF; switched to True after A/B testing confirmed it improves
#   routing spread without causing ruler-collapse at FIELD_POSITION_WEIGHT=0.30.
RESONANCE_MULTIPLIER_ENABLED = True
# RESONANCE_MULTIPLIER_THRESHOLD : cosine threshold for the Q4 post-collapse multiplier.
#   This operates in FULL 384-dim space (input_vec vs planet wave center), NOT the 3-axis
#   projection used by Phase-0D's RESONANCE_THRESHOLD=0.7. In 384-dim, MiniLM scatters
#   most prompt-vs-identity cosines around ±0.1, so a threshold of 0.7 would give sigmoid≈0
#   for every planet (measured: all multipliers <0.01 — catastrophic crush). Threshold=0.0
#   gives reasonable spread (0.38–0.71 range) as a gentle "you align with this question" nudge.
#   TUNABLE: lower it to make the multiplier more permissive; raise it to be stricter.
RESONANCE_MULTIPLIER_THRESHOLD = 0.0

# ─── PHASE 1 ROUTING / SPIKE DETECTION ─────────────────────────────────────
# FIELD_POSITION_WEIGHT : blend weight for the planet's field center, per Q1 approval.
#   field_center = w * wave_center_384d + (1 - w) * projected_orbital_position
#     w = 1.0 -> pure semantic identity (position ignored; static game map)
#     w = 0.0 -> pure orbital position (identity ignored; rigid spatial map)
#   Tuning this knob is a dial, NOT a rewrite: if the 3D projection starts causing
#   RULER-COLLAPSE (language compresses into a narrow cone), turn it DOWN toward identity.
#   "Identity travels with position" — the planet carries its psychological weight
#   along its orbital path. Start at 0.5 (balanced); nudge in Segment 2/4 tuning.
FIELD_POSITION_WEIGHT = 0.5
# FIELD_DISTANCE_METRIC : how routing measures "closeness" between the input and a
#   planet's field center (Segment 2). A TOGGLE, not an architecture choice — flip it to
#   A/B without rewriting anything:
#     "angular_z" -> per-input z-score of angular distances across all planets.
#                    MEASURED WINNER (tuning spike): MiniLM scatters real prompts ~90deg
#                    from ALL archetype texts, so raw angles cluster in a narrow band and
#                    no sigma can discriminate. Z-scoring makes the field self-calibrating
#                    per prompt: for every input the cohort mean is 0 and sd is 1 BY
#                    CONSTRUCTION, so "closest planet" always means something. Default.
#     "angular"   -> angular separation between unit directions (scale-invariant; reuses
#                    the exact comparison collapse.py already uses in Phase 0D). Kept for
#                    A/B — good when inputs are close to archetypes, weak on scattered prompts.
#     "euclidean" -> straight-line distance in 384-dim. Literal build-plan formula, but
#                    fragile: raw lifted positions sit at radius ~7-12 while inputs/
#                    identities are unit vectors (~1), so distances get dominated by that
#                    radius gap and the field can flatten (RULER-COLLAPSE family).
FIELD_DISTANCE_METRIC = "angular_z"
# SIGMA_SCALE : converts a planet's PLANET_SIGMA value into the spread used in the
#   Gaussian exp(-d^2 / 2 sigma_eff^2). In angular mode d is in radians, so this scales
#   sigma to radians. GUESS-tuned; nudge in Segment 4 like every other knob.
SIGMA_SCALE = 1.0

# Wave-speech mode for the collapse engine (collapse.py):
#   "vector" — dumb planets: each wave is its semantic anchor pulled by relevance. No LLM calls.
#   "llm"    — 7 distinct voices actually generate a 'piece' via the Ring/chamber model, then embed.
#              (Stub exists in collapse.emit_waves_llm; full build is a later phase.)
WAVE_SPEECH_MODE = "vector"

# ─── MULTI-PASS RECURSIVE FEEDBACK (Phase 0H — the Echo) ─────────────────────
# "Waves reacting to waves." A thought isn't a single splash: each planet feels how
# the rest of the system reacted (the tension/cancellation field) and adjusts its posture
# before the waveform is finally observed. Pass 1 = initial superposition; later passes feed
# that result back in so planets repel from their opponents and lean toward consensus.
#
# ECHO_ENABLED : master toggle. False -> single-pass, byte-identical to pre-0H behavior
#                (kept for debugging / A-B comparison). True -> ECHO_PASSES total passes.
# ECHO_PASSES  : total superposition passes including the initial splash. 2 = one echo.
ECHO_ENABLED = True
ECHO_PASSES = 2
# Gains below are GUESSES (tuned by feel, not real session data yet). Debug handles:
#   ECHO_TENSION_GAIN  — how much a planet pulls back when the field is tense overall.
#   ECHO_ALIGN_REPEL   — how hard each planet moves AWAY from the voices it cancelled
#                        against (the debate response; larger = more contrarian pushback).
#   ECHO_CONSENSUS_PULL— how strongly every wave leans toward the group consensus vector
