ECHO_TENSION_GAIN = 0.5
ECHO_ALIGN_REPEL = 0.35
ECHO_CONSENSUS_PULL = 0.12

# ─── PHASE 3 CHAMBER: MOON HEMISPHERE FRAMING (toggle, OFF by default) ────────
# The Build Plan's Phase A spec says each planet fires TWO shaped sub-perspectives
# before merging into one raw Id response:
#   LEFT moon  -> frames the response rationally / analytically.
#   RIGHT moon -> frames it intuitively / affectively (the felt sense).
# When MOON_HEMISPHERE_ENABLED is True, Phase A runs that two-lens split per planet
# and merges the lenses into a single Id response. When False (default), Phase A uses
# the original single raw-Id prompt — byte-for-byte identical to pre-toggle behavior,
# so existing test_phase_a/b/c.py results are unaffected until we deliberately flip it.
#
# This is a DIAL, not an architecture rewrite: turning it ON adds one extra LLM call
# per planet in Phase A (2 lenses + 1 merge) and is designed to be A/B'd later without
# touching any other phase. Kept OFF by default because the chamber just stabilized on
# the single-Id path; we flip it on when its own dedicated test segment runs.
MOON_HEMISPHERE_ENABLED = False
# How many words of raw Id each lens should produce before merging (guides the prompt).
MOON_LENS_MAX_TOKENS = 192
# Merged final Id response length budget (kept in line with the original Phase A's ~512).
MOON_MERGE_MAX_TOKENS = 512

# ─── PHASE 3 CHAMBER: COMET B→C BASIC TRIGGER CHECK (toggle, OFF by default) ──
# Per Build Plan Phase 3: between Ego (B) and Superego (C), a BASIC trigger fires —
#   "if the dominant planet has led for N consecutive sessions, a Comet appears with
#    a contrarian reframe prompt" and its line is folded into the Phase C discussion.
#
# This is the MINIMAL basic version only. The full 4-condition refinement (stagnation /
# over-seriousness / binary convergence / random 2% injection from comet/jester.json)
# is explicitly DEFERRED to Phase 8 — do NOT build that here. Keep it small.
#
# How "dominant" is decided: the planet with the highest routed weight for this input
# (max(routed_weights)). Cross-session history lives in a TINY state file next to the
# code (COMET_STATE_FILE) — deliberately minimal, NOT the Phase 4/8 memory machinery.
#
# Toggle OFF by default = existing test_phase_a/b/c.py results are byte-identical until
# we flip it on for its own dedicated test segment (same reasoning as the moon toggle).
COMET_TRIGGER_ENABLED = False
# Number of CONSECUTIVE sessions the same planet must have been #1 before the Comet
# appears. 3 matches John's "once is fluke, twice coincidence, three times pattern" rule.
# TUNABLE: raise to make it rarer, lower (2) to make it appear sooner.
# The comet FIRES the moment the dominant planet has now led for this many CONSECUTIVE
# sessions (i.e. on the N-th straight one). With 3: session1->no, session2->no, session3->yes.
COMET_CONSECUTIVE_SESSIONS = 3
# Once it has fired once, do NOT re-fire every single session during a long run. Instead
# stay quiet until the streak grows by another COMET_REFIRE_STEP consecutive sessions,
# then fire again. Deterministic (NOT random) so test logs stay repeatable; random
# re-firing is a Phase 8 refinement (comet/jester.json 'random_injection').
#   Fires at: 3, then 5, 7, 9...  (every COMET_REFIRE_STEP more straight sessions).
# A subject change (a DIFFERENT dominant planet) resets the streak to 1 automatically,
# so a genuinely new topic must rebuild to N before it can ever fire — no extra code.
COMET_REFIRE_STEP = 2
# Where the tiny cross-session dominant-planet history lives. Relative paths resolve
# next to this module's directory so it works from any CWD. A single JSON file holding
# {"streak_planet": <id or null>, "streak_count": int}.
COMET_STATE_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "comet_state.json")
# Max tokens for the Comet's contrarian reframe (kept small; it is one injected voice).
COMET_MAX_TOKENS = 256

