# ─── MEMORY / DECAY ──────────────────────────────────────────────────────────

MEMORY_MASS_BASE = 1.0         # M_u scale: mass = base * cosine(semantic, consensus) -> [0, base]
                               # (Paper III single-step form; full time-integral wired in sleep Pass V.)
DOMINANCE_ZONE_RATIO = 2.0     # Top planet weight > ratio*runner-up => dedicated planet_vault
MEMORY_POSITION_JITTER = 0.05  # Radial jitter so multiple entries per planet don't stack on one point
DECAY_GAMMA_BASE = 0.02        # Base decay rate per unit time (usage-frequency modulated)
MIN_ENTRY_MASS = 0.05          # Below this -> Black Hole compression queue
G1_DECAY_HALF_LIFE_WEEKS = None  # G1: effectively never decays (accumulation body)
G2_DECAY_HALF_LIFE_WEEKS = 4.0   # G2 self-model entries: ~4 week half-life

# ─── SLEEP CYCLE ──────────────────────────────────────────────────────────────

MICRO_SLEEP_IDLE_MINUTES = 30
DEEP_SLEEP_IDLE_HOURS = 3
STAGGER_INTERVAL_SECONDS = 5   # Per-planet Pass IV drift interval during deep sleep
WATCHKEEPER_COUNT = 3          # Planets that stay awake during deep sleep (min 1; prevents binary deadlock)

# ─── PHASE 6 RING: IDLE BEHAVIOR (Segment 4, toggle OFF by default) ─────────
# RING_IDLE_BEHAVIOR_ENABLED : master switch for generate_idle_reflection().
#   When False (default), the function returns a no-op string WITHOUT touching LM
#   Studio — so ring.py stays fully offline and the live flow is byte-identical to
#   pre-Segment-4 until John flips this on. When True, it makes ~1 LLM call reusing
#   cognitive_chamber._llm_chat_cached() and sources its "what you said earlier"
#   context from the Ring's recent swarm memory (capped by RING_IDLE_CONTEXT_ENTRIES).
# Kept OFF by default for the same reason as MOON_HEMISPHERE / COMET_TRIGGER:
# don't burn an LLM call in a path we haven't A/B'd on its own segment yet.
RING_IDLE_BEHAVIOR_ENABLED = False
# How many recent swarm entries to feed into the idle-reflection prompt. Kept small
# (2) deliberately: because Segment 2's write-everything + compression makes the swarm
# grow fast, a big context here would balloon the single LLM call against the 4090.
RING_IDLE_CONTEXT_ENTRIES = 2
# Max tokens for the ambient reflection — it is ONE short aside, not a full answer,
# so we keep it well under the ~512 budget used elsewhere (GUESS: 160).
RING_IDLE_MAX_TOKENS = 160
# Sampling temperature. Slightly higher than analytical passes because this is an
# ambient, human "thinking out loud" voice rather than a reasoned verdict.
RING_IDLE_TEMPERATURE = 0.8

# ─── PHASE 6 RING: MONTHLY SELF-REVIEW (Segment 5, toggle OFF by default) ─────
# D-009: at the 30-session mark OR calendar-month boundary -> G2 generates its
# change report -> routes through a FULL 7-planet debate (run_phase_a_b_c;
# all 7 must emit — anti-silence checked) -> verdict logged to G2's ring_buffer.
# RING_SELF_REVIEW_ENABLED : master switch. When False (default), the trigger and
#   runner are pure no-ops with ZERO LLM calls and never import cognitive_chamber
#   (same offline-safe pattern as MOON / COMET / IDLE toggles). Flip to True only
#   when you want a live review run (a ~21+ call burst — see 5b notes in Build Plan).
RING_SELF_REVIEW_ENABLED = False
# Session-count trigger: fire the self-review at this many completed sessions.
RING_SELF_REVIEW_SESSION_THRESHOLD = 30
# Report context caps (GUESS, flagged): how much history G2 may quote when it writes
# its change report. Kept small so the ~21+ call debate doesn't balloon against the
# 4090's ceiling — the debate itself is the expensive part, not the report.
RING_SELF_REVIEW_REPORT_TOPICS = 5     # recent topic labels fed to G2 for the report
RING_SELF_REVIEW_MAX_TOKENS = 384      # cap on the generated change report length

# ─── PHASE 7 GIANTS: G1 FILTER MOONS (Segment 2, toggle OFF by default in DEV) ──
# G1_FILTER_MOONS_ENABLED : master switch for g1_filter_moons.g1_filter_moons_pass().
#   When False (default — dev mode), Sleep Pass I skips the moons entirely and
#   behaves byte-identically to Segment 1 (zero LLM calls per candidate).
#
#   ⚠️ PRODUCTION RELEASE: Set this to True. The moons are a MANDATORY integrity
#   gate for G1's permanent archive — turning them off risks unverified data
#   entering the store. See Build Plan Phase 7 Seg 2 note.
#   In production, do NOT expose this as a user-facing runtime toggle; it should
#   be locked to True in the release config.
G1_FILTER_MOONS_ENABLED = False
# Relevance floor: candidates scoring below this are marked "peripheral" and
# promoted at reduced mass rather than full weight. GUESS — tune after first
# live run if the moons over- or under-demote.
G1_RELEVANCE_PERIPHERAL_FLOOR = 0.5
# Max tokens per moon LLM call. Kept small (256) because each moon makes ONE short
# JSON verdict, not a full response. Three moons × 256 tokens is cheap against the
# ~512-token budget used elsewhere in the chamber.
G1_MOON_MAX_TOKENS = 256

# ─── PHASE 7 GIANTS: G2 SELF-MODEL MOONS (Segment 3 — deterministic, no LLM) ──
# G2_MAGNITUDE_CAP : maximum per-session delta to the self-vector. A single wild
#   session cannot lurch the self-model more than this (normalized units). Gradual
#   accumulation across many sessions is allowed; sudden jumps are clamped and
#   flagged with status="clamped" for audit. GUESS — uncalibrated.
G2_MAGNITUDE_CAP = 0.15
# Escape threshold for the Consistency Gate: if a proposed vector delta's magnitude
# exceeds this, it is held for review as a potential gravitational-containment
# violation (the system "escaping" its own center of gravity). Set to 2× the
# magnitude cap so normal clamped changes pass through but genuinely wild deltas
# get caught. GUESS — tune after live runs.
G2_ESCAPE_THRESHOLD = G2_MAGNITUDE_CAP * 2  # 0.30

# ─── PHASE 7 GIANTS: G2 SANDBOX (Segment 4 — LLM-based, toggle OFF by default) ──
# G2_SANDBOX_ENABLED : master switch for g2_sandbox.try_candidate(). When False,
#   try_candidate() returns {"status": "skipped", ...} with ZERO LLM calls and does
#   NOT import collapse/resonance (offline-safe — same pattern as RING_IDLE_BEHAVIOR).
#   OFF in dev so sleep passes stay cheap; ON in production config.
G2_SANDBOX_ENABLED = False
# How many representative trial prompts to run per candidate. Each prompt runs the
# full pipeline with AND without the proposed change → 2 × N LLM-embedding calls.
# Kept small (3) for first live use; expandable once we trust the metrics.
G2_SANDBOX_TRIAL_PROMPTS = 3
# If applying the candidate shifts total tension by more than this, trial FAILS.
# (Matches g2_selfmodel.json "degradation_threshold.tension_shift_max".)
G2_SANDBOX_TENSION_SHIFT_MAX = 0.30
# If consensus coherence drops below this minimum, trial FAILS. Coherence is
# measured as cosine similarity between the baseline and candidate consensus vectors.
# (Matches g2_selfmodel.json "degradation_threshold.consensus_coherence_min".)
G2_SANDBOX_CONSENSUS_COHERENCE_MIN = 0.70

# ─── PHASE 7 GIANTS: G2 GROWTH POLICY / TIER SYSTEM (Segment 5 — deterministic, no LLM) ──
# TIER1 vs TIER2 boundary for a semantic-anchor / self-vector migration. A proposed
#   G2 change that migrates an anchor direction by MORE than this many normalized units
#   is STRUCTURAL → Tier 2 (held with status="pending_user_approval" until a reviewer
#   approves/rejects). At-or-below stays Tier 1 (autonomous after the moons pass).
# Matches g2_selfmodel.json "_growth_policy.tier_2_notify" (">0.3 units"). GUESS.
G2_TIER2_ANCHOR_MIGRATION = 0.30

# ─── GATE CONFIG PATHS ────────────────────────────────────────────────────────

GATES_CONFIG_PATH = "gates_config.json"

# ─── LM STUDIO CONNECTION ────────────────────────────────────────────────────

LM_STUDIO_HOST = "127.0.0.1"
LM_STUDIO_PORT = 1234
EMBEDDING_MODEL_ID = "text-embedding-allmini"  # confirmed via /v1/models (was a stale filename)
# Main model: auto-detected via /v1/models (first non-embedding available)

# M2 fix (independent-review triage): bounded retry + backoff for embedding calls.
# A single transient LM Studio hiccup (model reloading between calls, brief 5xx,
# connection refused) must not kill the whole pipeline. We retry a few times with
# exponential backoff, then raise a domain-specific EmbeddingUnavailableError instead
# of leaking a raw urllib error to the catch-all.
EMBED_RETRIES = 3                 # total attempts (1 initial + 2 retries). GUESS — tune if slow.
EMBED_RETRY_BACKOFF_S = 1.0       # base backoff; attempt n waits base * (2 ** (n-1)) seconds
# Canonical embedding dimensionality for this model family (all-MiniLM-L6-v2 = 384).
# Single source of truth used by collapse's session-history dir-length guard so a
# malformed persisted wave can't silently poison the superposition. Hardcoded to match
# the model (the AXIS_* vectors are also 384-dim; do not derive from them — they're
# defined later in this file and we want a stable constant here).
EMBEDDING_DIM = 384

